}

/* ============================================
   STORE LOCATOR
   ============================================ */
.store-locator-header {
  background: var(--green-light);
  padding: 40px 0;
}

.search-controls {
  display: flex;
  gap: 12px;
  align-items: center;
  max-width: 680px;
  margin: 0 auto;
}

.search-input-wrapper {
  flex: 1;
  position: relative;
}

.search-input-wrapper svg {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  color: var(--gray-500);
}

.search-input {
  width: 100%;
  padding: 14px 16px 14px 48px;
  border: 2px solid var(--gray-300);
  border-radius: 50px;
  font-size: 15px;
