.filter-btn:hover {
  border-color: var(--green);
  color: var(--green);
}

.filter-btn svg {
  width: 16px;
  height: 16px;
}

/* Filter Panel */
.filter-panel {
  display: none;
  max-width: 680px;
  margin: 16px auto 0;
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-md);
}

.filter-panel.open {
  display: block;
}

.filter-panel h4 {
  margin-bottom: 16px;
  font-size: 16px;
}

.filter-options {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.filter-chip {
  padding: 8px 16px;
  border: 2px solid var(--gray-300);
  border-radius: 50px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.filter-chip:hover,
.filter-chip.active {
  border-color: var(--green);
  background: var(--green-light);
  color: var(--green);
}

/* Order Type Toggle */
.order-type-toggle {
  display: flex;
  background: var(--gray-100);
  border-radius: 50px;
  padding: 4px;
  max-width: 300px;
  margin: 20px auto;
}

.order-type-btn {
  flex: 1;
  padding: 10px 24px;
  border-radius: 50px;
  font-size: 14px;
  font-weight: 600;
  text-align: center;
  transition: all 0.2s;
}

.order-type-btn.active {
  background: var(--green);
  color: var(--white);
}

/* Map + Results Layout */
.store-layout {
  display: grid;
  grid-template-columns: 400px 1fr;
  min-height: 500px;
}

.store-results {
  overflow-y: auto;
  max-height: 600px;
  border-right: 1px solid var(--gray-100);
}

.store-result-item {
  padding: 20px 24px;
  border-bottom: 1px solid var(--gray-100);
  cursor: pointer;
  transition: background 0.2s;
}

.store-result-item:hover {
  background: var(--green-light);
}

.store-result-item h4 {
  font-family: var(--font-body);
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}

.store-address {
  font-size: 14px;
  color: var(--gray-700);
  margin-bottom: 4px;
}

.store-hours {
  font-size: 13px;
  color: var(--gray-500);
}

.store-features {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.store-feature-tag {
  font-size: 11px;
  padding: 3px 10px;
  border-radius: 50px;
  background: var(--green-light);
  color: var(--green);
  font-weight: 600;
}

.map-container {
  background: var(--gray-100);
