}

.map-placeholder p {
  font-size: 14px;
}

/* ============================================
   MENU PAGE
   ============================================ */
.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 0;
  min-height: calc(100vh - var(--header-height));
}

.menu-sidebar {
  background: var(--white);
  border-right: 1px solid var(--gray-100);
  padding: 24px 0;
  position: sticky;
  top: var(--header-height);
  height: calc(100vh - var(--header-height));
  overflow-y: auto;
}

.menu-sidebar-group {
  margin-bottom: 24px;
}

.menu-sidebar-group h4 {
  padding: 0 24px;
  margin-bottom: 8px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--gray-500);
}

.menu-sidebar-group a {
  display: block;
  padding: 8px 24px;
  font-size: 14px;
  color: var(--gray-700);
  transition: all 0.15s;
}

.menu-sidebar-group a:hover,
.menu-sidebar-group a.active {
  color: var(--green);
  background: var(--green-light);
  font-weight: 600;
}

.menu-content {
  padding: 32px 40px;
}

.menu-category {
  margin-bottom: 48px;
}

.menu-category h2 {
  margin-bottom: 8px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--green);
  display: inline-block;
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
  margin-top: 24px;
}

.menu-item {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: pointer;
}

.menu-item:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}

.menu-item-image {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  color: var(--gray-500);
}

.menu-item-image.coffee { background: linear-gradient(135deg, #D7CCC8, #BCAAA4); }
.menu-item-image.tea { background: linear-gradient(135deg, #C8E6C9, #A5D6A7); }
.menu-item-image.cold { background: linear-gradient(135deg, #B3E5FC, #81D4FA); }
.menu-item-image.food { background: linear-gradient(135deg, #FFE0B2, #FFCC80); }
.menu-item-image.matcha { background: linear-gradient(135deg, #A5D6A7, #81C784); }
.menu-item-image.refreshing { background: linear-gradient(135deg, #F48FB1, #EC407A); }

.menu-item-info {
  padding: 14px;
}

.menu-item-info h4 {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 4px;
}

.menu-item-info p {
  font-size: 13px;
  color: var(--gray-500);
}

/* Breadcrumb */
.breadcrumb {
  padding: 16px 0;
  font-size: 13px;
  color: var(--gray-500);
  display: flex;
  align-items: center;
  gap: 8px;
}

.breadcrumb a {
  color: var(--green);
  font-weight: 500;
}

.breadcrumb span {
  color: var(--gray-500);
}

/* ============================================
   COOKIE BANNER
   ============================================ */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--forest);
  color: var(--white);
  padding: 24px;
  z-index: 200;
  transform: translateY(100%);
  transition: transform 0.4s ease;
}

.cookie-banner.visible {
  transform: translateY(0);
}

.cookie-banner-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.cookie-banner-text h4 {
  font-family: var(--font-body);
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 4px;
}

.cookie-banner-text p {
  font-size: 13px;
  opacity: 0.85;
  max-width: 600px;
}

.cookie-banner-actions {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}

/* ============================================
   FOOTER
   ============================================ */
.site-footer {
  background: var(--forest);
  color: var(--white);
  padding: 64px 0 24px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 16px;
  color: var(--cream);
}

.footer-col a {
  display: block;
  font-size: 13px;
  color: rgba(255,255,255,0.7);
  padding: 4px 0;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.15);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  font-size: 12px;
  color: rgba(255,255,255,0.5);
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.25);
