  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}

.footer-social a:hover {
  background: var(--green);
  border-color: var(--green);
}

.footer-social svg {
  width: 16px;
  height: 16px;
}

/* Mobile footer accordion */
.footer-accordion-heading {
  display: none;
  width: 100%;
  padding: 12px 0;
  font-size: 14px;
  font-weight: 700;
  color: var(--cream);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-accordion-heading svg {
  width: 18px;
  height: 18px;
  transition: transform 0.3s;
}

.footer-accordion-heading.open svg {
  transform: rotate(180deg);
}

.footer-accordion-content {
  overflow: hidden;
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-image {
    max-width: 320px;
  }

  .promo-split {
    grid-template-columns: 1fr;
  }

  .promo-card {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .promo-full {
    grid-template-columns: 1fr;
  }

  .promo-full-image {
    order: -1;
  }

  .tier-cards {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .partnership-cards {
    grid-template-columns: 1fr;
  }

  .business-gifting {
    grid-template-columns: 1fr;
  }

  .store-layout {
    grid-template-columns: 1fr;
  }

  .store-results {
    max-height: none;
    border-right: none;
    border-bottom: 1px solid var(--gray-100);
  }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: relative;
    top: auto;
    height: auto;
    border-right: none;
    border-bottom: 1px solid var(--gray-100);
    display: flex;
    overflow-x: auto;
    padding: 16px;
    gap: 16px;
  }

  .menu-sidebar-group {
    margin-bottom: 0;
    display: flex;
    gap: 8px;
    align-items: center;
  }

  .menu-sidebar-group h4 {
    padding: 0;
    white-space: nowrap;
  }

  .menu-sidebar-group a {
    padding: 6px 14px;
    white-space: nowrap;
    border-radius: 50px;
    font-size: 13px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  :root {
    --header-height: 64px;
  }

  .nav-primary,
  .nav-account {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero-inner {
    padding: 40px 24px;
  }

  .hero-image {
    display: none;
  }

  .ai-card {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .ai-card-icon {
    margin: 0 auto;
  }

  .section {
    padding: 56px 0;
  }

  .how-it-works-steps {
    grid-template-columns: 1fr;
    max-width: 360px;
    margin: 0 auto;
  }

  .tab-nav {
    gap: 2px;
  }

  .tab-btn {
    padding: 10px 14px;
    font-size: 13px;
  }

  .search-controls {
    flex-wrap: wrap;
  }

  .search-input-wrapper {
    flex: 1 1 100%;
  }

  .gift-card {
    flex: 0 0 160px;
  }

  .cookie-banner-inner {
    flex-direction: column;
    text-align: center;
  }

  .cookie-banner-actions {
    justify-content: center;
  }

  /* Footer accordion on mobile */
  .footer-accordion-heading {
    display: flex;
  }

  .footer-col h4 {
    display: none;
  }

  .footer-accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-accordion-content.open {
    max-height: 300px;
  }

  .footer-grid {
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }

  .menu-content {
    padding: 24px 16px;
  }

  .menu-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .app-badges {
    flex-direction: column;
    align-items: center;
  }
}

@media (max-width: 480px) {
  .menu-grid {
    grid-template-columns: 1fr;
  }

  .gift-card {
    flex: 0 0 140px;
  }

  .carousel-header h3 {
    font-size: 18px;
  }
}

