  .nav-primary,
  .nav-account {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero-inner {
    padding: 40px 24px;
  }

  .hero-image {
    display: none;
  }

  .ai-card {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .ai-card-icon {
    margin: 0 auto;
  }

  .section {
    padding: 56px 0;
  }

  .how-it-works-steps {
    grid-template-columns: 1fr;
    max-width: 360px;
    margin: 0 auto;
  }

  .tab-nav {
    gap: 2px;
  }

  .tab-btn {
    padding: 10px 14px;
    font-size: 13px;
  }

  .search-controls {
    flex-wrap: wrap;
  }

  .search-input-wrapper {
    flex: 1 1 100%;
  }

  .gift-card {
    flex: 0 0 160px;
  }

  .cookie-banner-inner {
    flex-direction: column;
    text-align: center;
  }

  .cookie-banner-actions {
    justify-content: center;
